      "text": "……其实我……",
      "speaker": "“爱理”",
      "chapter": "chapter3",
      "chapterTitle": "第三章 · 过去与现在",
      "scene": "S07A",
      "background": "bg-coast-night",
      "portrait": "portrait-airi",
